<?php
use App\Core\Db; require_once __DIR__.'/_common.php';
$pdo=Db::pdo(); $u=\App\Core\Auth::user(); $uid=(int)$u['id']; $rows=array();
if($pdo&&$uid){$st=$pdo->prepare("SELECT d.*,l.role_type current_role FROM cpms_approval_documents d LEFT JOIN cpms_approval_lines l ON l.document_id=d.id AND l.line_order=d.current_step_order WHERE d.created_by_id=:u OR EXISTS (SELECT 1 FROM cpms_approval_lines x WHERE x.document_id=d.id AND x.approver_id=:u) ORDER BY d.id DESC LIMIT 200");$st->execute(array(':u'=>$uid));$rows=$st->fetchAll();}
$cnt=array('recv'=>0,'mine'=>0,'prog'=>0,'rej'=>0); foreach($rows as $r){ if((int)$r['created_by_id']===$uid)$cnt['mine']++; $status=strtoupper($r['doc_status']); if($status==='PENDING')$cnt['prog']++; if($status==='REJECTED')$cnt['rej']++; }
?><div class="space-y-5"><div class="bg-gradient-to-r from-indigo-600 to-cyan-500 rounded-3xl p-7 text-white shadow-xl"><div class="flex justify-between"><div><h2 class="text-3xl font-extrabold">전자결재</h2><p class="mt-2 text-indigo-100">품의서와 휴가계를 작성하고 결재 진행상태를 확인합니다.</p></div><div class="space-x-2"><a class="px-4 py-2 rounded-xl bg-white text-indigo-700" href="?r=approval_create&type=proposal">품의서 작성</a><a class="px-4 py-2 rounded-xl bg-white/20" href="?r=approval_create&type=leave">휴가계 작성</a></div></div></div>
<div class="grid grid-cols-2 md:grid-cols-4 gap-3"><?php $cards=array('받은 결재'=>'recv','나의 요청'=>'mine','진행중'=>'prog','반려'=>'rej'); foreach($cards as $k=>$v){?><div class="bg-white rounded-2xl border p-4"><div class="text-gray-500"><?php echo h($k);?></div><div class="text-2xl font-extrabold"><?php echo (int)$cnt[$v];?></div></div><?php }?></div>
<div class="bg-white rounded-3xl border p-5 overflow-x-auto"><table class="w-full text-sm"><tr class="text-left border-b"><th>ID</th><th>종류</th><th>제목</th><th>작성자</th><th>상태</th><th>현재 단계</th><th>작성일시</th><th></th></tr><?php foreach($rows as $r){?><tr class="border-b"><td><?php echo (int)$r['id'];?></td><td><?php echo h(approval_doc_label($r['doc_type']));?></td><td><?php echo h($r['title']);?></td><td><?php echo h($r['created_by_name']);?></td><td><span class="px-2 py-1 rounded-full border <?php echo approval_status_badge($r['doc_status']);?>"><?php echo h($r['doc_status']);?></span></td><td><?php echo h($r['current_role']?$r['current_role']:'-');?></td><td><?php echo h($r['created_at']);?></td><td><a href="?r=approval_detail&id=<?php echo (int)$r['id'];?>" class="text-indigo-600">상세보기</a><?php if((int)$r['created_by_id']===$uid&&in_array($r['doc_status'],array('PENDING','DRAFT'))){?><form method="post" action="?r=approval_cancel" style="display:inline;"><input type="hidden" name="_csrf" value="<?php echo h(csrf_token());?>"><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><button class="text-rose-600 ml-2">요청취소</button></form><?php } ?></td></tr><?php } ?></table></div></div>